/* =====================================================
   FONT MONTSERRAT UNTUK pdfMake (Laporan Kejadian)
   Di-generate dari Google Fonts (Montserrat Regular/Bold/Italic/
   BoldItalic, subset Latin, versi v31), di-embed sebagai base64 TTF
   langsung ke virtual file system (vfs) pdfMake — bukan cuma dipakai
   di layar, tapi benar-benar tertanam di berkas PDF yang diunduh.
   Digabung (bukan menimpa) dengan window.KEJADIAN_VFS/KEJADIAN_FONTS
   di lib/fonts-carlito.js, lihat siapPdf() di kejadian.html.
   ===================================================== */

window.MONTSERRAT_VFS = {
  "Montserrat-Regular.ttf": "",
  "Montserrat-Bold.ttf": "",
  "Montserrat-Italic.ttf": "",
  "Montserrat-BoldItalic.ttf": ""
};

window.MONTSERRAT_FONTS = {
  Montserrat: {
    normal: "Montserrat-Regular.ttf",
    bold: "Montserrat-Bold.ttf",
    italics: "Montserrat-Italic.ttf",
    bolditalics: "Montserrat-BoldItalic.ttf"
  }
};
